window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-920a5861ca0d0374"]={"versions": [{"id": "FIG-920a5861ca0d0374", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines funktionalen Einzelschritts innerhalb der AUTOSAR E2E-Bibliothek (End-to-End-Kommunikationsabsicherung). Das Diagramm spezifiziert den Teilablauf „Write Length“ für das E2E-Profil 6 (E2E Profile 6) im Kontext der Sender- bzw. Weiterleitungsfunktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm referenziert zwei aufrufende Software-Funktionen bzw. Kontexte:</p>\n<ul class=\"fig-list\"><li><code>E2E_P06Protect()</code>\n</li><li><code>E2E_P06Forward()</code>\n</li></ul>\n<p class=\"fig-p\">Zentrale Entitäten und Datenstrukturen der Aktivität:</p>\n<ul class=\"fig-list\"><li><code>Data</code>: Byte-Array, das die zu übertragenden bzw. weiterzuleitenden Nutz- und Steuerdaten kapselt.\n</li><li><code>Offset</code>: Konfigurierter oder zuvor berechneter Byte-Offset im Datenpuffer.\n</li><li><code>Length</code>: 2 Byte langer Längenwert der Nutzdaten bzw. der E2E-geschützten Nachricht.\n</li><li>Zielbereich im Puffer: <code>Data[Offset+2...Offset+3]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss ist linear und besteht aus einem einzigen Aktionsschritt zwischen Start- und Endknoten:</p>\n<ol class=\"fig-list\"><li>Eintritt über den initialen Pseudozustand (Startknoten).\n</li><li>Ausführung der Aktion: „Copy 2-byte Length on bytes Data[Offset+2...Offset+3] in Big Endian order“. Hierbei wird der 16-Bit-Längenwert (<code>Length</code>) im Big-Endian-Format (Most Significant Byte zuerst) in die beiden aufeinanderfolgenden Bytes an den Indizes <code>Offset + 2</code> und <code>Offset + 3</code> des Datenarrays geschrieben.\n</li><li>Beendigung des Ablaufs im Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß AUTOSAR PRS E2E-Spezifikation (z. B. <code>[PRS_E2E_00425]</code>) ist dieser Schritt für Profil 6 in den Funktionen <code>E2E_P06Protect()</code> und <code>E2E_P06Forward()</code> normativ verbindlich umzusetzen. Entwickler müssen sicherstellen:</p>\n<ul class=\"fig-list\"><li>Die Bytereihenfolge des 2-Byte-Felds muss strikt Big Endian (Netzwerk-Byte-Order) sein, unabhängig von der Endianness der zugrundeliegenden Host-Mikrocontroller-Architektur.\n</li><li>Die Indizierung <code>Offset+2</code> und <code>Offset+3</code> setzt eine vorherige korrekte Ermittlung des Basis-Offsets (in Bytes) voraus.\n</li><li>Es muss sichergestellt sein, dass das Array <code>Data</code> über ausreichende Puffergröße verfügt, um Pufferüberläufe beim Schreiben auf <code>Offset+3</code> zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9c23df5c5ab5f98e", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung eines funktionalen Einzelschritts innerhalb der AUTOSAR E2E-Bibliothek (End-to-End-Kommunikationsabsicherung). Das Diagramm spezifiziert den Teilablauf „Write Length“ für das E2E-Profil 6 (E2E Profile 6) im Kontext der Sender- bzw. Weiterleitungsfunktionen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm referenziert zwei aufrufende Software-Funktionen bzw. Kontexte:</p>\n<ul class=\"fig-list\"><li><code>E2E_P06Protect()</code>\n</li><li><code>E2E_P06Forward()</code>\n</li></ul>\n<p class=\"fig-p\">Zentrale Entitäten und Datenstrukturen der Aktivität:</p>\n<ul class=\"fig-list\"><li><code>Data</code>: Byte-Array, das die zu übertragenden bzw. weiterzuleitenden Nutz- und Steuerdaten kapselt.\n</li><li><code>Offset</code>: Konfigurierter oder zuvor berechneter Byte-Offset im Datenpuffer.\n</li><li><code>Length</code>: 2 Byte langer Längenwert der Nutzdaten bzw. der E2E-geschützten Nachricht.\n</li><li>Zielbereich im Puffer: <code>Data[Offset+2...Offset+3]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss ist linear und besteht aus einem einzigen Aktionsschritt zwischen Start- und Endknoten:</p>\n<ol class=\"fig-list\"><li>Eintritt über den initialen Pseudozustand (Startknoten).\n</li><li>Ausführung der Aktion: „Copy 2-byte Length on bytes Data[Offset+2...Offset+3] in Big Endian order“. Hierbei wird der 16-Bit-Längenwert (<code>Length</code>) im Big-Endian-Format (Most Significant Byte zuerst) in die beiden aufeinanderfolgenden Bytes an den Indizes <code>Offset + 2</code> und <code>Offset + 3</code> des Datenarrays geschrieben.\n</li><li>Beendigung des Ablaufs im Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß AUTOSAR PRS E2E-Spezifikation (z. B. <code>[PRS_E2E_00425]</code>) ist dieser Schritt für Profil 6 in den Funktionen <code>E2E_P06Protect()</code> und <code>E2E_P06Forward()</code> normativ verbindlich umzusetzen. Entwickler müssen sicherstellen:</p>\n<ul class=\"fig-list\"><li>Die Bytereihenfolge des 2-Byte-Felds muss strikt Big Endian (Netzwerk-Byte-Order) sein, unabhängig von der Endianness der zugrundeliegenden Host-Mikrocontroller-Architektur.\n</li><li>Die Indizierung <code>Offset+2</code> und <code>Offset+3</code> setzt eine vorherige korrekte Ermittlung des Basis-Offsets (in Bytes) voraus.\n</li><li>Es muss sichergestellt sein, dass das Array <code>Data</code> über ausreichende Puffergröße verfügt, um Pufferüberläufe beim Schreiben auf <code>Offset+3</code> zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-920a5861ca0d0374", "to": "FIG-9c23df5c5ab5f98e", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
